// procedures to override, read attribute values

task write_attr;
  input  [`SDFEC_LD_ADDR_SZ-1:0] addr;
  input  [`SDFEC_LD_DATA_SZ-1:0] data;
  begin
    ATTR[addr] = data;
    trig_attr = ~trig_attr; // to be removed
  end
endtask

function [`SDFEC_LD_DATA_SZ-1:0] read_attr;
  input  [`SDFEC_LD_ADDR_SZ-1:0] addr;
  begin
    read_attr = ATTR[addr];
  end
endfunction

task commit_attr;
  begin
trig_attr = ~trig_attr;
  end
endtask
